import{_ as r,o as l,c as e,ag as a}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"Skill 与 MCP 的异同","description":"","frontmatter":{},"headers":[],"relativePath":"AI/skill-vs-mcp.md","filePath":"AI/skill-vs-mcp.md"}'),o={name:"AI/skill-vs-mcp.md"};function d(s,t,i,n,g,h){return l(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="skill-与-mcp-的异同" tabindex="-1">Skill 与 MCP 的异同 <a class="header-anchor" href="#skill-与-mcp-的异同" aria-label="Permalink to &quot;Skill 与 MCP 的异同&quot;">​</a></h1><p>两者经常一起出现在 Agent 产品里，但<strong>不是一类东西</strong>，也<strong>不互相替代</strong>。可以先用一句话分开：</p><ul><li><strong>Skill</strong>：教 Agent「按什么流程做事」（流程 / 规范 / 提示资产）</li><li><strong>MCP</strong>：给 Agent「连上什么外部能力」（协议 / 工具 / 数据通道）</li></ul><p>更完整的专题见：<a href="./skill.html">Skill 技能文件详细说明</a>、<a href="./mcp.html">MCP 是什么</a>。</p><h2 id="对比一览" tabindex="-1">对比一览 <a class="header-anchor" href="#对比一览" aria-label="Permalink to &quot;对比一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Skill</th><th>MCP</th></tr></thead><tbody><tr><td><strong>本质</strong></td><td>可复用的执行说明书（多为 <code>SKILL.md</code> + 脚本/参考资料）</td><td>Host ↔ Server 的开放通信协议</td></tr><tr><td><strong>主要回答的问题</strong></td><td>什么时候触发、步骤顺序、输出长什么样、哪些事不能做</td><td>如何发现工具、如何传参、如何拿回结果</td></tr><tr><td><strong>形态</strong></td><td>Markdown / 目录化知识与流程</td><td>可运行的 Server 进程 + JSON-RPC</td></tr><tr><td><strong>运行位置</strong></td><td>通常由 Host / Agent 在适当时机加载进上下文</td><td>独立进程或远程服务，经 Client 接入</td></tr><tr><td><strong>典型产出</strong></td><td>更稳定的行为与交付物格式</td><td>查库、读文件、调 API 等真实副作用或数据</td></tr><tr><td><strong>复用方式</strong></td><td>复制 Skill 目录、装到 Skill 市场、团队内共享规范</td><td>同一个 Server 可被多个 Host 插拔使用</td></tr><tr><td><strong>和模型的关系</strong></td><td>约束「怎么想、怎么做」</td><td>扩展「能碰什么外部世界」</td></tr></tbody></table><h2 id="相同点" tabindex="-1">相同点 <a class="header-anchor" href="#相同点" aria-label="Permalink to &quot;相同点&quot;">​</a></h2><ul><li>都是为了让 Agent <strong>更可控、更可复用</strong>，而不是每次从零临时发挥</li><li>都可以沉淀为团队资产（Skill 库 / MCP Server 仓库）</li><li>都可以和 Cursor、Claude Code 等 Host 组合使用</li></ul><h2 id="不同点-选型时最关键" tabindex="-1">不同点（选型时最关键） <a class="header-anchor" href="#不同点-选型时最关键" aria-label="Permalink to &quot;不同点（选型时最关键）&quot;">​</a></h2><ul><li>要固化「代码评审怎么做、发布前查什么」→ 写 <strong>Skill</strong></li><li>要让 Agent 真正调用 GitHub / 浏览器 / 内部 RPC → 接 <strong>MCP</strong></li><li>Skill 里也可以调用脚本；但脚本仍是「流程的一部分」。若希望能力被多个产品以标准方式发现和调用，更适合抽成 <strong>MCP Server</strong></li></ul><h2 id="怎么配合" tabindex="-1">怎么配合 <a class="header-anchor" href="#怎么配合" aria-label="Permalink to &quot;怎么配合&quot;">​</a></h2><p>一个很常见的组合是——Skill 规定流程，MCP 提供手脚。例如「系统化排障」Skill 写明：先收集上下文 → 再查日志 → 再给结论；其中「查日志 / 查监控」可以由 MCP Server 提供工具，Skill 负责保证步骤不漏、输出格式统一。</p><p><strong>一句话：Skill 管流程，MCP 管连接；按需叠加，而不是二选一。</strong></p>',13)])])}const S=r(o,[["render",d]]);export{k as __pageData,S as default};
